### 層 2：REST API Endpoint（AIDV-268）

```typescript
// server/routes/v1/videos.ts — Express/Hono route（與 tRPC 並存）

// POST /api/v1/videos
// Authorization: Bearer aidv_<key>
interface CreateVideoRequest {
  title: string;
  script_content: string;
  aspect_ratio?: '16:9' | '9:16' | '1:1';
  output_spec?: { resolution?: string; fps?: number; codec?: string };
  webhook_url?: string;     // 覆蓋帳號預設 webhook
}

interface CreateVideoResponse {
  id: string;               // videoProject UUID
  status: 'queued';
  estimated_duration_sec: number;
  webhook_registered: boolean;
}

// 鑑權 middleware（API key 路徑）
async function apiKeyAuth(req, res, next) {
  const raw = req.headers.authorization?.replace('Bearer ', '');
  if (!raw?.startsWith('aidv_')) return res.status(401).json({ error: 'Invalid API key format' });
  const hash = crypto.createHash('sha256').update(raw).digest('hex');
  const { data: keyRecord } = await supabase
    .from('apiKeys')
    .select('userId, scopes, revoked_at, expires_at')
    .eq('key_hash', hash)
    .single();
  if (!keyRecord || keyRecord.revoked_at || (keyRecord.expires_at && new Date(keyRecord.expires_at) < new Date()))
    return res.status(401).json({ error: 'API key invalid or expired' });
  req.apiUserId = keyRecord.userId;
  req.apiScopes = keyRecord.scopes;
  next();
}
```

**Rate limiting**：`api/v1/*` 路徑套用 `100 req/min per API key`（Upstash Redis 或記憶體 LRU）

