**Webhook Dispatcher**（`server/lib/webhookDispatch.ts`）：

```typescript
interface WebhookPayload {
  event: 'video.completed' | 'video.failed';
  video_id: string;
  created_at: string;
  data: {
    title: string;
    output_url?: string;    // video.completed 時有值
    duration_sec?: number;
    error?: string;         // video.failed 時有值
  };
}

export async function dispatchWebhook(userId: string, payload: WebhookPayload): Promise<void> {
  const configs = await getActiveWebhooks(userId, payload.event);
  await Promise.allSettled(
    configs.map(async (config) => {
      const body = JSON.stringify(payload);
      const signature = crypto
        .createHmac('sha256', config.secret)
        .update(body)
        .digest('hex');
      await fetch(config.url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-AIDV-Signature': `sha256=${signature}`,
          'X-AIDV-Event': payload.event,
        },
        body,
        signal: AbortSignal.timeout(10_000),  // 10s timeout
      });
    })
  );
}
```

